#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# GridForge-AI — patch 0001 bootstrap (capacity envelope engine)
#
# Self-contained: no network, no patch file, nothing to upload. Either run this
# script, or paste its entire contents into the Codespace terminal.
#
# It puts everything at the repository ROOT, on ONE branch (main), and commits
# with Claude credited as a co-author. Additive only: it creates new paths and
# refuses to clobber anything that already exists.
# ---------------------------------------------------------------------------
set -euo pipefail

ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"
echo "repo: $ROOT"

# --- one branch: land on main, drop the feature branch ----------------------
git rev-parse --verify main >/dev/null 2>&1 || { echo "no 'main' branch here"; exit 1; }
CUR="$(git rev-parse --abbrev-ref HEAD)"
if [ "$CUR" != "main" ]; then
  git stash push -u -m "pre-gridforge-$(date +%s)" >/dev/null 2>&1 || true
  git checkout main
fi
git branch -D feat/envelope-engine >/dev/null 2>&1 || true

# --- refuse to overwrite existing work --------------------------------------
for p in gridforge tests examples pyproject.toml Makefile; do
  if [ -e "$p" ]; then
    echo "ERROR: '$p' already exists at the repo root."
    echo "Patch 0001 is additive and will not overwrite it. Move or rename it first,"
    echo "or extract to a scratch directory and merge by hand."
    exit 1
  fi
done

